public Node insert(Node root, int val) {
    Node newNode = new Node(val);
    if (root == null) return newNode;

    Node current = root;
    Node parent = null;

    while (current != null) {
        parent = current;
        if (val < current.val) {
            current = current.left;
        } else if (val > current.val) {
            current = current.right;
        } else {
            return root; // duplicate, skip
        }
    }

    if (val < parent.val) {
        parent.left = newNode;
    } else {
        parent.right = newNode;
    }
    return root;
}

